using Azure.Storage.Files.Shares;

var shareUri = new Uri("https://demostorageaccount.file.core.windows.net/app-files");
var shareClient = new ShareClient(shareUri, new DefaultAzureCredential());
await shareClient.CreateIfNotExistsAsync();

var directory = shareClient.GetDirectoryClient("exports");
await directory.CreateIfNotExistsAsync();

var fileClient = directory.GetFileClient("customers.csv");
await fileClient.UploadAsync("customers.csv", overwrite: true);

var download = await fileClient.DownloadAsync();
using var stream = File.OpenWrite("customers-copy.csv");
await download.Value.Content.CopyToAsync(stream);
